"use client";

/**
 * Reads the org/actor/flag context installed by the dashboard layout.
 */
import { useContext } from "react";
import { OrgContext, type OrgContextValue } from "./org-context";
import type { FeatureFlagSnapshot } from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type { Organization } from "@/types/organization";

/** Throws rather than returning a half-built tenant context — a client
 *  component rendered outside `[orgSlug]` is a routing bug, not a state. */
export function useOrgContext(): OrgContextValue {
  const value = useContext(OrgContext);
  if (value === null) {
    throw new Error(
      "useOrg() must be rendered inside the dashboard <OrgProvider>.",
    );
  }
  return value;
}

export function useOrg(): {
  org: Organization;
  actor: Actor;
  flags: FeatureFlagSnapshot;
} {
  const { org, actor, flags } = useOrgContext();
  return { org, actor, flags };
}
"use client";

/**
 * The per-request tenant context the dashboard layout installs.
 *
 * Everything below `[orgSlug]` needs the same three values — the organization,
 * the resolved `Actor` and the evaluated flag snapshot — plus the quota checks
 * the billing service already computed for the shell. Passing those down by
 * props through every component would be noise, so the layout renders one
 * `OrgProvider` and `useOrg()` / `usePermission()` / `usePlanLimits()` read it.
 */
import { createContext, type ReactElement, type ReactNode } from "react";
import type { LimitCheck } from "@/types/billing";
import type { FeatureFlagSnapshot } from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type { Organization } from "@/types/organization";

export interface OrgContextValue {
  readonly org: Organization;
  readonly actor: Actor;
  readonly flags: FeatureFlagSnapshot;
  /** Quota checks for the current billing period, or `[]` when not loaded. */
  readonly limitChecks: readonly LimitCheck[];
}

export const OrgContext = createContext<OrgContextValue | null>(null);

export interface OrgProviderProps {
  readonly value: OrgContextValue;
  readonly children?: ReactNode;
}

export function OrgProvider(props: OrgProviderProps): ReactElement {
  return (
    <OrgContext.Provider value={props.value}>
      {props.children}
    </OrgContext.Provider>
  );
}
/**
 * Compact issue summary tile used by lists and the board.
 */
import Link from "next/link";
import { Avatar } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Card } from "@/components/ui/card";
import { cn } from "@/lib/cn";
import { formatRelative, isOverdue } from "@/lib/date";
import { humanizePriority, humanizeStatus } from "@/lib/format";
import type { Issue, IssueLabel, IssuePriority } from "@/types/issue";
import type { User } from "@/types/member";
import type { ReactElement } from "react";
import { PRIORITY_TONE, STATUS_TONE } from "./issue-tone";

export type IssueCardProps = {
  issue: Issue;
  assignee?: User | null;
  labels?: readonly IssueLabel[];
  href: string;
  compact?: boolean;
};

/** Priorities worth shouting about; `none`/`low` stay silent on a card. */
function shouldShowPriority(priority: IssuePriority): boolean {
  return priority !== "none" && priority !== "low";
}

export function IssueCard(props: IssueCardProps): ReactElement | null {
  const { issue, assignee = null, labels = [], href, compact = false } = props;
  const overdue = isOverdue(issue.dueAt);

  return (
    <Card padded={!compact} className="issue-card">
      <div className={cn("flex items-start gap-3", compact && "text-sm")}>
        <div className="min-w-0 flex-1">
          <Link href={href} className="block font-medium hover:underline">
            <span className="mr-2 text-neutral-500">#{issue.number}</span>
            {issue.title}
          </Link>

          <div className="mt-1 flex flex-wrap items-center gap-2">
            <Badge tone={STATUS_TONE[issue.status]} size="sm">
              {humanizeStatus(issue.status)}
            </Badge>

            {shouldShowPriority(issue.priority) ? (
              <Badge tone={PRIORITY_TONE[issue.priority]} size="sm">
                {humanizePriority(issue.priority)}
              </Badge>
            ) : null}

            {labels.map((label) => (
              <Badge key={label.id} tone="neutral" size="sm">
                {label.name}
              </Badge>
            ))}

            {issue.dueAt !== null ? (
              <span className={cn("text-xs", overdue && "text-red-600")}>
                {overdue ? "overdue " : "due "}
                {formatRelative(issue.dueAt)}
              </span>
            ) : null}

            {issue.archivedAt !== null ? (
              <Badge tone="warning" size="sm">
                Archived
              </Badge>
            ) : null}
          </div>
        </div>

        {assignee !== null ? (
          <Avatar name={assignee.name} src={assignee.avatarUrl} size="sm" />
        ) : (
          <Badge tone="neutral" size="sm">
            Unassigned
          </Badge>
        )}
