    expect(isOverdue(null, REFERENCE)).toBe(false);
  });

  it("treats a due date as a whole day: overdue only once that day has ended", () => {
    // Earlier the same day is not overdue yet, whatever the time of day.
    expect(isOverdue(iso("2026-03-15T00:00:00.000Z"), REFERENCE)).toBe(false);
    expect(isOverdue(iso("2026-03-15T11:59:59.000Z"), REFERENCE)).toBe(false);
    expect(isOverdue(iso("2026-03-15T23:59:59.999Z"), REFERENCE)).toBe(false);
    expect(isOverdue(iso("2026-03-14T23:59:59.999Z"), REFERENCE)).toBe(true);
    expect(
      isOverdue(iso("2026-03-15T23:59:59.999Z"), new Date("2026-03-16T00:00:00.000Z")),
    ).toBe(true);
  });

  it("takes the due day on the workspace clock", () => {
    // 15 Mar 23:00 in Tokyo is 14:00Z; Tokyo's 15 Mar ends at 15:00Z.
    const due = iso("2026-03-15T14:00:00.000Z");
    expect(isOverdue(due, new Date("2026-03-15T14:59:59.999Z"), "Asia/Tokyo")).toBe(false);
    expect(isOverdue(due, new Date("2026-03-15T15:00:00.000Z"), "Asia/Tokyo")).toBe(true);
    // The same instant is still 15 Mar in UTC, so not overdue there yet.
    expect(isOverdue(due, new Date("2026-03-15T15:00:00.000Z"), "UTC")).toBe(false);
    expect(() => isOverdue(due, REFERENCE, "Mars/Olympus")).toThrow(RangeError);
  });

  it("reads the local calendar date of an instant", () => {
