    // New York springs forward on 8 Mar 2026: the day began at EST midnight.
    expect(startOfLocalDay(new Date("2026-03-08T15:00:00.000Z"), "America/New_York")).toBe(
      "2026-03-08T05:00:00.000Z",
    );
    expect(startOfLocalDay(new Date("2026-03-09T15:00:00.000Z"), "America/New_York")).toBe(
