    const viaService = await updateOrganization(t.actors.owner, { orgId: t.org.id, settings: { timeZone: "Europe/Berlin" } });
    expect(viaService.settings.timeZone).toBe("Europe/Berlin");
  });

  it("overdue sweep and stats follow the workspace clock", async () => {
    const t = await createTenant("tz-overdue");
    await orgRepo.updateOrg(t.org.id, { orgId: t.org.id, settings: { timeZone: "Asia/Tokyo" } });
    await usageRepo.recomputeUsage(t.org.id);
