    const n = await issueRepo.nextIssueNumber(t.org.id, t.project.id);
    const issue = await issueRepo.insertIssue(issueInput(t.org.id, t.project.id, { dueAt: "2026-06-01T10:00:00.000Z" }), t.userIds.owner, n);
    const n2 = await issueRepo.nextIssueNumber(t.org.id, t.project.id);
    const closed = await issueRepo.insertIssue(issueInput(t.org.id, t.project.id, { dueAt: "2026-05-01T10:00:00.000Z" }), t.userIds.owner, n2);
    await issueRepo.setIssueStatus(t.org.id, closed.id, "done");
    const seen: string[] = [];
    const off = subscribe("issue.overdue", (p) => { seen.push(p.issueId); });
    await runOverdueIssueJob(new Date("2026-06-01T14:59:59.000Z"));
    expect(seen).toEqual([]);
    await runOverdueIssueJob(new Date("2026-06-01T15:00:00.000Z"));
    expect(seen).toEqual([issue.id]);
    off();

    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date("2026-06-01T14:59:59.000Z"));
    expect((await getProject(t.actors.member, t.org.id, t.project.slug)).stats.overdueIssues).toBe(0);
    vi.setSystemTime(new Date("2026-06-01T15:00:00.000Z"));
    expect((await getProject(t.actors.member, t.org.id, t.project.slug)).stats.overdueIssues).toBe(1);
    const list = await listProjects(t.actors.member, { orgId: t.org.id, limit: 10, cursor: null });
    expect(list.items[0]?.stats.overdueIssues).toBe(1);
