      vi.useFakeTimers({ toFake: ["Date"] });
      vi.setSystemTime(new Date(iso));
      const n = await notificationRepo.insertNotification(t.org.id, { orgId: t.org.id, recipientId: t.userIds.member, kind: "comment_created", title, body: title, href: "/x", actorId: null, channels: ["email"] });
      vi.useRealTimers();
      return n;
    };
    await at("2026-05-30T23:59:00.000Z", "too old");
    await at("2026-05-31T12:00:00.000Z", "inside");
    const newer = await at("2026-06-01T00:10:00.000Z", "newer");
    const send = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);
    await runDigestEmailJob(new Date("2026-06-01T09:30:00.000Z")); // Tokyo 18:30 - not hour
    expect(send).not.toHaveBeenCalled();
    await runDigestEmailJob(new Date("2026-06-01T00:30:00.000Z")); // Tokyo 09:30
    expect(send).toHaveBeenCalledTimes(1);
    const html = send.mock.calls[0]?.[0].html ?? "";
    expect(html).toContain("<td>entryCount</td><td>1</td>");
    expect(html).toContain("2026-05-31T00:00:00.000Z");
    expect(html).toContain("2026-06-01T00:00:00.000Z");
    const unread = await notificationRepo.listUnreadSince(t.org.id, t.userIds.member, "2026-01-01T00:00:00.000Z" as never);
    expect(unread.map((u) => u.title).sort()).toEqual(["newer", "too old"]);
    expect(newer.readAt).toBeNull();
    await runDigestEmailJob(new Date("2026-06-01T00:45:00.000Z"));
    expect(send).toHaveBeenCalledTimes(1);
  });

  it("retention cut-off is local midnight N calendar days ago", () => {
    expect(retentionCutoff(new Date("2026-06-01T07:00:00.000Z"), 30, "UTC")).toBe("2026-05-02T00:00:00.000Z");
    expect(retentionCutoff(new Date("2026-06-01T07:00:00.000Z"), 30, "Asia/Tokyo")).toBe("2026-05-01T15:00:00.000Z");
    // across DST: NY, 90 days before 2026-06-01 is 2026-03-03 (EST)
    expect(retentionCutoff(new Date("2026-06-01T12:00:00.000Z"), 90, "America/New_York")).toBe("2026-03-03T05:00:00.000Z");
  });

  it("migrates an old database without time_zone", async () => {
    const dir = mkdtempSync(join(tmpdir(), "tz-mig-"));
    const path = join(dir, "old.db");
    const db = new Database(path);
    db.exec(`CREATE TABLE organizations (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL, slug TEXT NOT NULL, owner_id TEXT NOT NULL, plan TEXT NOT NULL DEFAULT 'free', logo_url TEXT, trial_ends_at TEXT, default_issue_status TEXT NOT NULL DEFAULT 'backlog', allow_public_projects INTEGER NOT NULL DEFAULT 0, require_two_factor INTEGER NOT NULL DEFAULT 0, digest_hour_utc INTEGER NOT NULL DEFAULT 7, enabled_flag_overrides TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, archived_at TEXT)`);
    db.exec(`INSERT INTO organizations (id, name, slug, owner_id, created_at, updated_at) VALUES ('o1','n','s','u','x','x')`);
    db.close();
    await runMigrations(path);
    await runMigrations(path);
    const check = new Database(path);
    expect(check.prepare("SELECT time_zone FROM organizations").get()).toEqual({ time_zone: "UTC" });
    check.close();
  });
});
